// Bridge between OML-generated TaskConfig and kernel TaskDescriptor.
// Hand-written — not regenerated by the OML transpiler.

use crate::generated::task_schema::TaskConfig;
use crate::memory::task::TaskDescriptor;

impl TaskConfig {
    /// Construct a `TaskDescriptor` from this config.
    ///
    /// `id` is the unique task identifier assigned at boot.
    /// `stack_base` is the address of the statically allocated stack buffer;
    /// the initial `stack_ptr` is set to `stack_base + stack_size`.
    pub fn into_descriptor(self, id: u8, stack_base: usize) -> TaskDescriptor {
        TaskDescriptor::with_capabilities(
            id,
            self.priority,
            stack_base,
            self.stack_size as usize,
            self.memory_start as usize,
            self.memory_end as usize,
            self.exclusive_cap_mask,
            self.shared_cap_mask,
            self.required_cap_mask,
        )
    }
}
